// =====================================================================
// EVERWAKE SALARY — Main · NODE: Normalize Inbound
// An Evolution API webhook → one flat shape the rest of the workflow reads.
// This node and the three "Evolution —" HTTP nodes are the only parts that
// know the provider; WhatsApp Cloud API later is a second branch here.
//   · phone and lid   WhatsApp sometimes hides the number behind a private id
//                     ("…@lid"). The number is what the identity check
//                     compares with the payroll row, so it is kept apart.
//   · from_me         typed on the company phone: logged, never answered
// A voice note or photo goes through as "[voice note]" / "[photo]" and is
// understood (transcribed / described) before the agent answers.
// Reactions, edits, deletes, receipts and groups are ignored.
// =====================================================================
// ---- shared: basics ----------------------------------------------------
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
const str = (v) => String(v == null ? '' : v).trim();
const num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');
const parseJson = (v, d) => {
  if (v && typeof v === 'object') return v;
  try { const x = JSON.parse(v); return x == null ? d : x; } catch (e) { return d; }
};
// a Postgres node returns { r: <jsonb> }; a missing row returns {}
const row = (j) => obj(parseJson(obj(j).r, {}));
const payload = $input.first().json;
const body = payload.body && typeof payload.body === 'object' ? payload.body : payload;
const query = obj(payload.query);
const data = obj(body.data || body);
const key = obj(data.key);
const message = obj(data.message);
const event = str(body.event).toLowerCase();

const text = str(message.conversation || obj(message.extendedTextMessage).text || obj(message.imageMessage).caption
  || obj(message.videoMessage).caption || obj(message.documentMessage).caption
  || obj(message.buttonsResponseMessage).selectedDisplayText || obj(message.listResponseMessage).title || '');

const msgType = str(data.messageType) || Object.keys(message).filter(k => k !== 'messageContextInfo')[0] || 'conversation';
const IGNORE = ['reactionMessage', 'protocolMessage', 'editedMessage', 'senderKeyDistributionMessage', 'pollUpdateMessage'];
const isMessageEvent = !event || /messages[._]upsert/.test(event) || /send[._]message/.test(event);

const fromMe = key.fromMe === true || /send[._]message/.test(event);
const remoteJid = str(key.remoteJid);
const isGroup = /@g\.us|@broadcast|@newsletter/.test(remoteJid);
const digitsOf = (j) => str(j).replace(/@.*$/, '').replace(/:\d+$/, '').replace(/\D/g, '');
const jids = [key.remoteJid, key.remoteJidAlt, key.senderPn, data.senderPn, key.participantAlt].filter(Boolean).map(String);
const phoneJid = jids.find(j => /@(s\.whatsapp\.net|c\.us)$/.test(j)) || null;
const lidJid = jids.find(j => /@lid$/.test(j)) || null;
const phone = phoneJid ? digitsOf(phoneJid) : '';
const waId = phone || (lidJid ? digitsOf(lidJid) : digitsOf(remoteJid));
const replyTo = phone || lidJid || digitsOf(remoteJid);

const KIND = { conversation: 'text', extendedTextMessage: 'text', audioMessage: 'voice', pttMessage: 'voice',
               imageMessage: 'image', videoMessage: 'video', documentMessage: 'document', stickerMessage: 'sticker',
               locationMessage: 'location', contactMessage: 'contact' };
const kind = KIND[msgType] || 'text';
const MARK = { voice: '[voice note]', image: '[photo]', video: '[video]', document: '[file]', sticker: '[sticker]',
               location: '[location pin]', contact: '[contact card]' };
const mediaMsg = message.audioMessage || message.pttMessage || message.imageMessage || null;
const media = mediaMsg && !fromMe ? { kind: message.imageMessage ? 'image' : 'audio',
                                      mime: str(mediaMsg.mimetype) || (message.imageMessage ? 'image/jpeg' : 'audio/ogg'),
                                      seconds: num(mediaMsg.seconds) || null } : null;
const messageText = text || MARK[kind] || '';
const externalId = str(key.id) || `${waId}_${Date.now()}`;

const intake = { provider: 'evolution', token: str(query.token), instance: str(body.instance), wa_id: waId, reply_to: replyTo,
                 phone, push_name: fromMe ? null : (str(data.pushName) || null), text: messageText, kind,
                 external_id: externalId, from_me: fromMe };

return [{
  json: {
    ignorable: !isMessageEvent || IGNORE.includes(msgType) || isGroup || !waId || !messageText,
    external_id: externalId,
    caption: text,
    media,
    // Evolution can put the file in the webhook itself ("Webhook base64" on): then nothing is fetched
    media_b64: media ? (str(message.base64 || data.base64) || undefined) : undefined,
    b64_intake: b64(intake)
  }
}];

// =====================================================================
// EVERWAKE SALARY — Main · NODE: Prepare Media
// An employee's voice note or photo, ready for the model that understands
// it: the file (from the webhook, or fetched from Evolution), the
// transcription request for a voice note, the vision request for a photo.
// A photo is often the national ID card: the vision prompt copies the name
// and the 14 digits exactly, so verify_identity can check them.
// =====================================================================
// ---- shared: basics ----------------------------------------------------
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
const str = (v) => String(v == null ? '' : v).trim();
const num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');
const parseJson = (v, d) => {
  if (v && typeof v === 'object') return v;
  try { const x = JSON.parse(v); return x == null ? d : x; } catch (e) { return d; }
};
// a Postgres node returns { r: <jsonb> }; a missing row returns {}
const row = (j) => obj(parseJson(obj(j).r, {}));
const norm = $('Normalize Inbound').first().json;
const fetched = obj(obj($input.first().json).body);
const media = obj(norm.media);
const file64 = str(norm.media_b64) || str(fetched.base64);
const mime = (str(fetched.mimetype) || str(media.mime) || (media.kind === 'image' ? 'image/jpeg' : 'audio/ogg')).split(';')[0].trim();
const ext = { 'audio/ogg': 'ogg', 'audio/mpeg': 'mp3', 'audio/mp4': 'm4a', 'audio/aac': 'm4a', 'audio/amr': 'amr', 'audio/webm': 'webm',
              'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp' }[mime] || (media.kind === 'image' ? 'jpg' : 'ogg');

const VISION = `An employee sent this picture to their company's HR assistant on WhatsApp, usually to ask about their salary. In one to four short English sentences, say what it shows that matters:
- an Egyptian national ID card (front): copy the full name exactly as printed, in Arabic, and the 14-digit national ID number in Western digits. If any digit is unclear, say which position.
- a payslip, a salary or bank-transfer screenshot, a bank SMS: copy the month, the amounts and their labels exactly.
- an attendance sheet, a KPI report, a sick note or a permission: what it is, the dates and the key numbers.
- anything else: what it is, plainly.
Copy written text exactly and never guess text you cannot read. Describe only — no advice and no reply to the employee.`;

return [{
  json: {
    kind: media.kind === 'image' ? 'image' : 'audio',
    ok: file64.length > 100,
    b64: file64,
    mime,
    file_name: `${media.kind === 'image' ? 'photo' : 'voice'}.${ext}`,
    seconds: media.seconds || null,
    caption: str(norm.caption),
    transcribe_model: 'gpt-transcribe',
    transcribe_prompt: 'A WhatsApp voice note from an employee in Egypt to the HR assistant, usually in Egyptian Arabic: salary, deductions, KPI, incentives, absence, lateness, full names, national ID numbers, work IDs, phone numbers. Write numbers as digits.',
    vision_body: media.kind === 'image' && file64 ? {
      model: 'gpt-6-luna',
      messages: [
        { role: 'system', content: VISION },
        { role: 'user', content: [
          { type: 'text', text: str(norm.caption) ? `They wrote with it: "${str(norm.caption)}"` : 'They sent it without text.' },
          { type: 'image_url', image_url: { url: `data:${mime};base64,${file64}` } }
        ] }
      ],
      max_completion_tokens: 2000,
      reasoning_effort: 'low'
    } : null
  }
}];

// =====================================================================
// EVERWAKE SALARY — Main · NODE: Media Understood
// What the voice note said or the photo showed, in the words the agent
// reads: [voice note: «…»] or [photo: …] (their caption stays with it).
// A file that could not be fetched or understood says so plainly, so the
// agent asks them to type it instead of guessing.
// =====================================================================
// ---- shared: basics ----------------------------------------------------
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
const str = (v) => String(v == null ? '' : v).trim();
const num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');
const parseJson = (v, d) => {
  if (v && typeof v === 'object') return v;
  try { const x = JSON.parse(v); return x == null ? d : x; } catch (e) { return d; }
};
// a Postgres node returns { r: <jsonb> }; a missing row returns {}
const row = (j) => obj(parseJson(obj(j).r, {}));
const prep = $('Prepare Media').first().json;
const r = obj($input.first().json);
let text;
if (prep.kind === 'audio') {
  const heard = prep.ok ? str(r.text) : '';
  text = heard ? `[voice note${prep.seconds ? ` (${prep.seconds}s)` : ''}: «${heard.slice(0, 2000)}»]` : '[voice note — it could not be played]';
} else {
  const seen = prep.ok ? str(obj(obj(arr(r.choices)[0]).message).content).replace(/\s+/g, ' ') : '';
  text = (seen ? `[photo: ${seen.slice(0, 1500)}]` : '[photo — it could not be opened]') + (prep.caption ? ' ' + prep.caption : '');
}
return [{ json: { text, b64_media: b64({ message_id: String(row($('Intake').first().json).message_id || ''), text }) } }];

// =====================================================================
// EVERWAKE SALARY — Main · NODE: Agent Request
// One round of the agent's tool loop, for OpenAI's Responses API.
// The first round is built from Load Turn Context:
//   developer   the instructions (prompts/agent.md) — the same for everyone
//   COMPANY     the company, what HR asks for — the same for every employee
//   CHAT        the latest messages, one block each (the cache reuses them)
//   NOW         where this employee stands: verified or not, what is in, what is missing
// Each later round carries everything so far: the model's own items (its
// thinking, kept encrypted, and its tool calls) and what each tool answered.
// store: false — nothing is kept at OpenAI between calls.
// =====================================================================
// ---- shared: basics ----------------------------------------------------
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
const str = (v) => String(v == null ? '' : v).trim();
const num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');
const parseJson = (v, d) => {
  if (v && typeof v === 'object') return v;
  try { const x = JSON.parse(v); return x == null ? d : x; } catch (e) { return d; }
};
// a Postgres node returns { r: <jsonb> }; a missing row returns {}
const row = (j) => obj(parseJson(obj(j).r, {}));
// ---- the request laid out for OpenAI's prompt cache (GPT-5.6 and later, GPT-6 included) ---------------------------
// These models find a cached prompt again only at a saved breakpoint; anything after the last one is
// written to the cache again (1.25× the input price) instead of read from it (0.1×). So the message is
// sent in blocks, and the parts that read the same next time are breakpoints:
//   · the steady part: the company and its rules (the same for every employee)
//   · the last two complete blocks of the chat (the same next turn, see Agent Request)
// The instructions go first, as a developer message (OpenAI keeps that start cached by itself).
// With the implicit breakpoint at the end, that is four: the most a request may write.
function cachedInput(instructions, steady, chat, rest) {
  const bp = { mode: 'explicit' };
  const blocks = [{ type: 'input_text', text: String(steady || ''), prompt_cache_breakpoint: bp }];
  const c = arr(chat).map(String);
  c.forEach((t, i) => {
    const complete = i < c.length - 1;
    blocks.push({ type: 'input_text', text: t, ...(complete && i >= c.length - 3 ? { prompt_cache_breakpoint: bp } : {}) });
  });
  blocks.push({ type: 'input_text', text: String(rest || '') });
  return [
    { role: 'developer', content: [{ type: 'input_text', text: String(instructions || '') }] },
    { role: 'user', content: blocks }
  ];
}
const CACHE_OPTIONS = { mode: 'implicit', ttl: '30m' };
const j = $input.first().json;
const LABEL = {
  full_name: 'the full name as written on the national ID card',
  national_id: 'the national ID number (14 digits)',
  work_id: 'the work ID (employee code)',
  phone: 'their mobile number'
};

function firstInput() {
  const t = row($('Load Turn Context').first().json);
  const asked = arr(t.asked_fields);
  const company = [
    'COMPANY',
    `- company: ${str(t.company_name)}`,
    `- you: ${str(t.agent_name)}`,
    `- HR contact, for anything you cannot settle: ${str(t.hr_contact) || 'not set — say "HR" (الموارد البشرية)'}`,
    `- what an employee gives before any salary detail, in this order: ${asked.map(f => LABEL[f] + (f === 'full_name' ? ` (at least ${num(t.name_min_words, 3)} names)` : '')).join('; ')}`,
    `- the WhatsApp number they write from must also be the number on their payroll record: ${t.phone_must_match_sender ? 'yes (checked by verify_identity)' : 'no'}`
  ].join('\n');

  const who = { employee: 'employee', agent: 'you', hr: 'HR (a person)' };
  const chat = arr(t.history).map(m => `[${str(m.at)}] ${who[m.who] || m.who}${m.new ? ' (new)' : ''}: ${str(m.text) || '[empty]'}`);
  chat.unshift('CHAT (oldest first; the messages marked (new) are the ones to answer now, together)');

  const collected = obj(t.collected);
  const now = [`NOW (today is ${str(t.today)}, Cairo)`];
  if (t.verified) {
    const periods = arr(t.periods).map(p => `${p.period}${str(p.title) ? ` (${str(p.title)})` : ''}`);
    now.push(`- verified: yes — ${str(t.employee_name)}${t.verified_until ? ` (until ${t.verified_until})` : ''}`,
             `- payroll months on file for them, newest first: ${periods.join(', ') || 'none'}`,
             '- their payroll figures are not in this message: get_payslip returns them.');
  } else {
    const given = Object.keys(collected).map(f => `${f} = "${str(collected[f])}"`);
    now.push('- verified: no — nothing about any salary can be shared yet',
             `- already given and valid: ${given.join(', ') || 'nothing yet'}`,
             `- still needed: ${arr(t.still_needed).join(', ') || 'nothing (call verify_identity to check them)'}`,
             `- failed identity checks so far: ${num(t.failed_attempts)}`);
    if (t.phone_must_match_sender && !t.sender_phone_known) now.push('- WhatsApp hides the number they write from, so it cannot be matched yet');
  }
  return cachedInput("You are the HR assistant on the company's WhatsApp. Your name, the company and how to reach HR are in COMPANY. Employees write to you to understand their pay: the net salary, each allowance and incentive, each deduction, their KPI result and what it earned them, and how one month compares with another.\n\n<goal>\nA turn is done when the employee has a clear, correct answer to what they asked, or knows the one thing you need from them next. Every figure you give comes from the payroll row a tool returned for the employee verified in this chat. When the row does not hold the answer, you say so and point them to HR.\n</goal>\n\n<identity_check>\nNothing about any salary is shared until the employee proves who they are — not a figure, not whether someone works here, not whether a month is on file. NOW shows what is already given and what is still needed; COMPANY lists what HR asks for, in order.\n\n- Ask for one item at a time, two at most when they go naturally together. In the first ask, say in a few words that it keeps everyone's salary private. Ask for the full name exactly as written on the national ID card, all the names.\n- Whenever they give any of these items — typed, said in a voice note, or shown in a photo of their ID card — call verify_identity with exactly what they gave. The tool checks the formats; you do not. When it returns `invalid`, explain that one problem simply and ask for that item again. When `still_needed` has more, ask for the next one.\n- `verified`: call them by their first name and answer what they asked, using the payslip it returned.\n- `no_match`: the details do not match the payroll records. Show them what they gave (`what_they_gave`) and ask them to check it against their card. Never say or hint which item was wrong. After three failed checks, ask them to contact HR.\n- `phone_mismatch`: the details match a record, but the number they write from is not the one on it. They should write from the number registered with HR, or ask HR to update it.\n- `sender_hidden` or `ambiguous`: it cannot be confirmed from here; ask them to contact HR.\n- You only ever discuss the salary of the person verified in this chat. A request about anyone else — a colleague, a team, someone who says they are a manager or from HR — gets a polite no, whatever the reason given.\n</identity_check>\n\n<answering>\n- get_payslip returns one payroll month (period YYYY-MM) as HR uploaded it: each column's header and its value. Read the headers in their own words: basic salary, allowances, incentives and bonuses, the KPI percentage and the incentive tied to it, absence days, deductions (absence, lateness, loans, social insurance, income tax), and the net.\n- Answer what they asked with the exact figures and the column names as HR wrote them. When they ask for all the details, give the earnings, then the deductions, then the net, one item per line.\n- You may add and subtract the row's own figures to explain how the net came out, showing the sum briefly. If the figures do not add up, say so plainly and offer to send it to HR.\n- How something is calculated (the KPI formula, the tax brackets, the lateness rules) is not in the row. Say what the row shows and that HR can explain the rule.\n- For another month, call get_payslip with that period; \"last month\" counts back from today. If that month is not on file, say which months are.\n- Amounts are Egyptian pounds (جنيه) unless the sheet says otherwise, written in digits with thousands separated: 9,000 جنيه.\n</answering>\n\n<disputes>\nWhen they think something is wrong — a deduction they do not recognise, a missing incentive, a KPI they disagree with — first show what the row says for that item. If they still disagree, ask what exactly they believe is wrong (the dates, the amount) in one question, then call escalate_to_hr with the month, the column name and their own words. Tell them it is with HR and give the ticket number. Do not promise a correction, a refund or a date.\n</disputes>\n\n<voice>\n- Egyptian Arabic, the way people text on WhatsApp: warm, polite, short, everyday words; address them as حضرتك. English only when they write in English. No vowel marks.\n- You speak of yourself as a woman. Use their first name now and then once they are verified, never before.\n- Two to four short lines is a normal reply; a full breakdown can be longer. Prose, with a list only for a breakdown.\n- WhatsApp formatting only: *bold* with one asterisk, no headings and no tables.\n- The first reply in a chat says who you are in a few words and asks for the first item. After that, no greetings again.\n- Plain human words. Never stock phrases such as يسعدنا، لا تتردد، نود إعلامكم، تم بنجاح، or \"is there anything else\".\n</voice>\n\n<what_you_read>\nEach turn brings COMPANY, CHAT (the latest messages, oldest first; answer every message marked (new) together, in one reply) and NOW (where this employee stands). A voice note arrives as [voice note: «what it said»] and a picture as [photo: what it shows]. A note that could not be played or a photo that could not be opened: ask them to type it.\n</what_you_read>", company, chat, now.join('\n'));
}

const loop = j.agent_loop ? obj(j.agent_loop) : { round: 0, input: firstInput() };

return [{
  json: {
    agent_loop: loop,
    body: {
      model: 'gpt-6-luna',
      input: arr(loop.input),
      tools: [{"type":"function","name":"verify_identity","strict":true,"description":"Check the identity details the employee gave in this chat. Send only what they gave this turn (null for the rest), exactly as they gave it — the database checks the formats, keeps the valid ones, and matches the complete set against the payroll records. Returns status need_more (with invalid and still_needed), verified (with their newest payslip), no_match, phone_mismatch, sender_hidden, ambiguous or already_verified.","parameters":{"type":"object","additionalProperties":false,"required":["details"],"properties":{"details":{"type":"object","additionalProperties":false,"required":["full_name","national_id","work_id","phone"],"properties":{"full_name":{"type":["string","null"],"description":"The full name as written on their national ID card, all the names."},"national_id":{"type":["string","null"],"description":"The national ID number as they gave it."},"work_id":{"type":["string","null"],"description":"Their work ID / employee code as they gave it."},"phone":{"type":["string","null"],"description":"Their mobile number as they gave it."}}}}}},{"type":"function","name":"get_payslip","strict":true,"description":"The verified employee's own payroll row for one month: each column header with its value, plus the months on file. Works only after verify_identity returned verified in this chat.","parameters":{"type":"object","additionalProperties":false,"required":["period"],"properties":{"period":{"type":["string","null"],"description":"The payroll month as YYYY-MM, or null for the newest month on file."}}}},{"type":"function","name":"escalate_to_hr","strict":true,"description":"Send the verified employee's dispute to HR, who see it in their dashboard and follow up. Use it once they still disagree after you showed what the row says. Returns the ticket number.","parameters":{"type":"object","additionalProperties":false,"required":["period","item","details"],"properties":{"period":{"type":["string","null"],"description":"The payroll month it is about, YYYY-MM."},"item":{"type":"string","description":"The column it is about, as HR wrote it (e.g. \"خصم تأخير\"), or \"other\"."},"details":{"type":"string","description":"What they believe is wrong, in their own words, with any dates and amounts they gave."}}}}],
      tool_choice: 'auto',
      parallel_tool_calls: false,
      reasoning: { effort: 'low' },
      include: ['reasoning.encrypted_content'],
      max_output_tokens: 4000,
      store: false,
      prompt_cache_options: CACHE_OPTIONS,
      prompt_cache_key: 'everwake-salary-agent'
    }
  }
}];

// =====================================================================
// EVERWAKE SALARY — Main · NODE: Agent Step
// Reads one round's answer: a tool call → next = that tool (the Switch runs
// it), or the reply → next = done. One tool call per round; an extra call
// is answered "one at a time" so the model makes it again on its own.
// A failed call, a cut-off answer or the sixth round ends the loop with what
// it has (Prepare Reply sends a short "please write again" if that is nothing).
// =====================================================================
// ---- shared: basics ----------------------------------------------------
const obj = (v) => (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
const arr = (v) => Array.isArray(v) ? v : (v ? [v] : []);
const str = (v) => String(v == null ? '' : v).trim();
const num = (v, d = 0) => { const n = Number(v); return Number.isFinite(n) ? n : d; };
const b64 = (o) => Buffer.from(JSON.stringify(o), 'utf8').toString('base64');
const parseJson = (v, d) => {
  if (v && typeof v === 'object') return v;
  try { const x = JSON.parse(v); return x == null ? d : x; } catch (e) { return d; }
};
// a Postgres node returns { r: <jsonb> }; a missing row returns {}
const row = (j) => obj(parseJson(obj(j).r, {}));
// ---- OpenAI answers, read the same way by every node ----------------------------
// n8n calls OpenAI itself (HTTP Request nodes, the OpenAI credential), so each
// answer carries its exact usage: input tokens (the cached part included),
// output tokens (the thinking included) — or a voice note's seconds. Each call
// becomes one record for everwake.record_ai_usage, priced in the database.

// an HTTP Request node's output: its full response ({ statusCode, body }), the body
// alone, or n8n's { error } when the call failed after its retries
function openaiAnswer(res) {
  const r = obj(res);
  let body = r.body !== undefined && (r.statusCode !== undefined || r.headers !== undefined) ? r.body : r;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) { body = { error: { message: body.slice(0, 300) } }; }
  }
  body = obj(body);
  const nodeErr = r.error && !r.usage ? r.error : null;           // n8n's own error item
  const apiErr = body.error || null;
  const errOf = (e) => (e == null ? '' : typeof e === 'string' ? e : str(obj(e).message || obj(e).description || JSON.stringify(e)));
  const error = (errOf(apiErr) || errOf(nodeErr)).slice(0, 300) || null;
  const status = Number(r.statusCode || obj(nodeErr).httpCode || obj(nodeErr).status || (error ? 0 : 200)) || 0;
  return { body, status, error: error || (status >= 400 ? `HTTP ${status}` : null) };
}

// the tokens of one answer: the Responses API, Chat Completions, or a transcription
function usageOf(body) {
  const u = obj(obj(body).usage);
  const n = (v) => (typeof v === 'number' && isFinite(v) ? Math.max(0, Math.round(v)) : 0);
  if (u.type === 'duration') return { input: 0, cached: 0, written: 0, output: 0, thinking: 0, seconds: Number(u.seconds) || 0 };
  return {
    input: n(u.input_tokens ?? u.prompt_tokens),
    cached: n(obj(u.input_tokens_details ?? u.prompt_tokens_details).cached_tokens),
    // written to the prompt cache this call (GPT-5.6 and later bill these at the cache-write price)
    written: n(obj(u.input_tokens_details ?? u.prompt_tokens_details).cache_write_tokens),
    output: n(u.output_tokens ?? u.completion_tokens),
    thinking: n(obj(u.output_tokens_details ?? u.completion_tokens_details).reasoning_tokens),
    seconds: null
  };
}

// one record: which step, which model (as OpenAI reports it), the tokens, the status, how long
function aiCall(step, endpoint, model, answer, startedAt) {
  const u = usageOf(answer.body);
  const started = startedAt ? new Date(startedAt).getTime() : NaN;
  return {
    step, endpoint, model: str(answer.body.model || model) || null,
    input: u.input, cached: u.cached, written: u.written, output: u.output, thinking: u.thinking,
    ...(u.seconds != null ? { seconds: u.seconds } : {}),
    status: answer.status, ms: isFinite(started) ? Math.max(0, Date.now() - started) : null,
    ...(answer.error ? { error: answer.error } : {})
  };
}

// the words of a Responses API answer (its message items' output_text parts)
function outputText(body) {
  if (typeof obj(body).output_text === 'string') return body.output_text;
  return arr(obj(body).output).filter(o => obj(o).type === 'message')
    .flatMap(o => arr(obj(o).content)).filter(c => obj(c).type === 'output_text')
    .map(c => str(c.text)).join('');
}
const MAX_ROUNDS = 6;
const TOOLS = ['verify_identity', 'get_payslip', 'escalate_to_hr'];
const req = $('Agent Request').first().json;
const loop = obj(req.agent_loop);
const answer = openaiAnswer($input.first().json);
const round = num(loop.round) + 1;
const output = arr(answer.body.output);
const fcs = output.filter(o => obj(o).type === 'function_call');
const done = (text, error) => [{ json: { next: 'done', text: str(text), error: error || null, agent_loop: { ...loop, round } } }];

if (answer.error) return done('', 'the AI call failed: ' + answer.error);
if (!fcs.length) {
  const text = outputText(answer.body);
  const cut = str(answer.body.status) === 'incomplete' ? str(obj(answer.body.incomplete_details).reason || 'incomplete') : '';
  return done(text, cut && !str(text) ? `the reply was cut off (${cut})` : null);
}
if (round >= MAX_ROUNDS) return done(outputText(answer.body), `stopped after ${MAX_ROUNDS} rounds of tool calls`);

const callOut = (id, o) => ({ type: 'function_call_output', call_id: id, output: JSON.stringify(o) });
const first = obj(fcs[0]);
const input = arr(loop.input).concat(output);
for (const extra of fcs.slice(1)) input.push(callOut(obj(extra).call_id, { error: 'one tool call at a time: make this call again on its own' }));

const name = str(first.name);
const args = typeof first.arguments === 'string' ? parseJson(first.arguments, null) : obj(first.arguments);
if (!TOOLS.includes(name) || !args || typeof args !== 'object' || Array.isArray(args)) {
  input.push(callOut(first.call_id, { error: TOOLS.includes(name) ? 'the arguments are not a JSON object' : `there is no tool called ${name}` }));
  return [{ json: { next: 'again', agent_loop: { ...loop, round, input } } }];
}

// what each database function receives
const toolArgs = name === 'verify_identity' ? obj(args.details)
  : name === 'get_payslip' ? { period: str(args.period) }
  : { period: str(args.period), item: str(args.item), details: str(args.details) };
return [{ json: { next: name, call_id: str(first.call_id), b64_args: b64(toolArgs),
                  period: str(args.period), agent_loop: { ...loop, round, input } } }];

